// Inert frames where the reference site loads third-party pixels and ads.
// The workload doesn't run third-party code, but keeps the frames, because
// the number of child frames changes the cost of every missed global lookup
// on the window (such as Apollo's globalThis.__DEV__ check).
import { memo } from "react";
import styles from "./AdSlots.module.css";

const PIXEL_NAMES = ["universal_pixel_p7xk2", "universal_pixel_q91mz", "tag_frame_ads_1", "tag_frame_measure", "sync_frame_1", "sync_frame_2", "consent_frame", "sign_in_frame"];

export default memo(function AdSlots({ count = PIXEL_NAMES.length, visibleSlots = 0 }) {
    const frames = [];
    for (let i = 0; i < count; i++) {
        const visible = i < visibleSlots;
        frames.push(
            <iframe
                key={i}
                name={PIXEL_NAMES[i % PIXEL_NAMES.length]}
                title={visible ? "Advertisement" : "Tracking frame"}
                srcDoc="<!doctype html><title></title>"
                className={visible ? styles.slot : styles.pixel}
                tabIndex={-1}
                aria-hidden="true"
                width={visible ? 300 : 0}
                height={visible ? 250 : 0}
            />,
        );
    }
    return <div className={styles.frames}>{frames}</div>;
});
